198:    * Draws the strip, and puts it on the timeline.
199:    *
200:    * The window is the element that moves, so this holds the one node it needs and
201:    * looks nothing up. What it used to do was append markup, find the `<image>` in
202:    * it again by class name, and read the frame geometry back out of the attributes
203:    * the markup had just serialised.
204:    */
205:   private draw(strip: BoardStrip): void {
206:     const window = fromMarkup(boardStripMarkup(strip)).firstElementChild as SVGSVGElement;
207:     this.figure.append(window);
208:     this.selectSource(window);
209:     this.animations.register(this.id, {
210:       frameCount: strip.frameCount,
211:       setFrame: (frame) => {
212:         setAttrs(window, { viewBox: boardStripWindow(strip, frame) });
213:         this.syncSelectionCue();
214:       },
215:     }, strip.clips);
216:     this.playing = true;
217:     if (strip.playing) this.animations.play(this.id, strip.playing);
218:   }
