387:   effect(picture: BoardPicture): BoardEffect {
388:     // An effect is placed at a cell's centre, so its origin is already its middle.
389:     const drawing = new SvgEffect(
390:       this.animations,
391:       svg('g', { class: 'fx' }),
392:       0,
393:       `strip:${this.serial++}`,
394:       picture,
395:     );
396:     this.layers.effects.append(drawing.el);
397:     return drawing;
398:   }
